/* Category icons only. Series retain their existing cover images. */
const catalogFocusIconPaths={"magnetic-48": "<path d='M3 6h26v4H3zM9 10v5m14-5v5M5 16l5-2 3 9-5 2zM19 15h7v9h-7z'/><path d='m8 25 5-2M20 24h5M13 8h5'/>", "three-phase-220": "<path d='M3 5h26M3 8h26M3 11h26M8 11v5m16-5v5M5 17h6v8H5zM21 17h6v8h-6z'/><path d='M6 25h4m12 0h4M29 4v8'/>", "linear-systems": "<path d='M4 6h24v5H4zM4 15h15v5H4zM22 15h6v11h-6z'/><path d='M5 11h22M5 20h13m4 5h6'/>", "modular-recessed": "<rect x='4' y='4' width='10' height='10' rx='1.5'/><rect x='18' y='4' width='10' height='10' rx='1.5'/><rect x='4' y='18' width='10' height='10' rx='1.5'/><rect x='18' y='18' width='10' height='10' rx='1.5'/><circle cx='9' cy='9' r='2.5'/><circle cx='23' cy='9' r='2.5'/><circle cx='9' cy='23' r='2.5'/><circle cx='23' cy='23' r='2.5'/>", "outdoor": "<path d='M3 28h26M9 28V15h7v13M8 15v-4h9v4M23 28V7m-4 0h8l-2-4h-4z'/><path d='M10 15h5m5-6-2 3m8-3 2 3'/>", "surface-fixtures": "<path d='M3 5h26M6 5v15m9-15v15m5-15v10m7-10v10'/><ellipse cx='10.5' cy='20' rx='4.5' ry='2.5'/><ellipse cx='23.5' cy='15' rx='3.5' ry='2'/><path d='M7 21.5h7m7-5h5'/>", "hybrid": "<path d='M5 5h16v3H5zM13 8v5m0 0h7M5 5v20h3'/><path d='m20 11 7 7-7 7-7-7z'/><path d='m20 24 6-6'/><path d='M9 28h7'/>", "wall": "<path d='M5 3v26M5 17h13v-5M15 6h6l4 8H11l4-8ZM18 14v4'/><path d='M13 14h10'/><path d='M14 21l-1 3m5-3v5m4-5 1 3'/>", "retail-48": "<path d='M6 4v24M26 4v24M3 28h6m14 0h6M6 8h20M6 19h20M6 25h20M14 8v4'/><path d='m12 12 5-1 2 6-5 1z'/><path d='M14 18l4-1M9 19h14'/>", "led-strip": "<ellipse cx='12' cy='14' rx='8' ry='9'/><ellipse cx='12' cy='14' rx='4' ry='5'/><path d='M12 23h16v5H12c-4 0-7-2-7-5'/><path d='M16 24.5v2m5-2v2m5-2v2'/><path d='M8 6v2m9 0v2'/>", "led-profile": "<path d='M5 5h5v17h12V5h5v22H5zM10 8h12M10 12h12'/><path d='M12 19h8'/>", "power-supplies": "<rect x='4' y='8' width='24' height='17' rx='1'/><path d='M8 8V4m5 4V4m6 4V4m5 4V4M8 25v3m16-3v3M8 13h4m-2-2v4m11-2h4M17 12l-3 6h5l-3 5'/>", "lighting-controls": "<path d='M7 4v24M16 4v24M25 4v24'/><rect x='4' y='9' width='6' height='5' rx='1' fill='#FFF1E8'/><rect x='13' y='19' width='6' height='5' rx='1' fill='#FFF1E8'/><rect x='22' y='7' width='6' height='5' rx='1' fill='#FFF1E8'/>"};
function catalogFocusIcon(key){return `<svg viewBox="0 0 48 48" width="48" height="48" fill="none" stroke="currentColor" stroke-linecap="butt" stroke-linejoin="miter" stroke-miterlimit="3" aria-hidden="true"><rect class="catalog-icon-background" x="2" y="2" width="44" height="44" rx="8" fill="#FFF1E8" stroke-width="2"/><g transform="translate(8 8)" stroke-width="1.8">${catalogFocusIconPaths[key]||catalogFocusIconPaths['surface-fixtures']}</g></svg>`}
const catalogCategoryIconKeys={0:'magnetic-48',1:'three-phase-220',2:'linear-systems',3:'modular-recessed',4:'outdoor',5:'surface-fixtures',6:'hybrid',7:'wall',8:'retail-48',9:'led-strip',10:'led-profile',11:'power-supplies',12:'lighting-controls'};
const originalIconCategorySelector=selectCatalogCategory;
selectCatalogCategory=function(n,updateUrl=true){originalIconCategorySelector(n,updateUrl);const heading=$('#catalog-native-content .unified-system-heading');if(!heading)return;const image=heading.querySelector('.unified-system-image');const icon=document.createElement('span');icon.className='catalog-focus-detail-icon';icon.setAttribute('aria-hidden','true');icon.innerHTML=catalogFocusIcon(catalogCategoryIconKeys[n]);if(image)image.replaceWith(icon);else heading.appendChild(icon)};
function decorateCategoryNavigation(){const root=$('.focus-catalog-list');if(!root)return;root.querySelectorAll('[data-catalog-category]').forEach(b=>{if(b.querySelector('.catalog-option-icon'))return;const icon=document.createElement('span');icon.className='catalog-option-icon';icon.innerHTML=catalogFocusIcon(catalogCategoryIconKeys[Number(b.dataset.catalogCategory)]);b.prepend(icon);b.classList.add('catalog-icon-option')})}
const originalIconCatalogSwitch=catalogSwitch;
catalogSwitch=function(section,updateUrl=true){originalIconCatalogSwitch(section,updateUrl);if(section==='categories')decorateCategoryNavigation()};
if(!$('#menu').hidden)catalogSwitch(catalogSection,false);
document.fonts.ready.then(()=>{if(!$('#menu').hidden)catalogSwitch(catalogSection,false)});
